 "Miếu này không có người trông coi... Có thứ gì đó đã bị bỏ quên ở đây.": "这座庙无人看守……有什么东西被遗忘在这里。",
 "Không thấy ánh sáng nào phía rừng. Hương cũ và gió luồn qua rễ đa.": "林那边不见一点光。旧香与风穿过榕根。",
