 "Qua kẽ lá, một mảnh mái ngói cũ thoáng hiện.": "透过叶隙，一角旧瓦顶一闪而现。",
 "Có nhà thật. Nhưng cổng ở đâu? Mình chưa thấy lối nào dẫn tới đó.": "真的有房子。可门在哪儿？我没看见有路通到那里。",
 "Giữa những tán cây chỉ có một mảng mái ngói tối, không hề thấy đèn.": "树冠之间只有一片昏暗的瓦顶，不见一点灯火。",
