 "BIỆT THỰ · 21:20": "别墅 · 21:20",
 "Cổng sắt buộc xích. Sau song sắt là ngôi nhà bỏ hoang.": "铁门被铁链锁住。栅栏之后是一座荒废的宅子。",
 "Biệt thự Vân Hòa... Bà ngoại tớ chưa bao giờ muốn nhắc tới nơi này.": "Vân Hòa 别墅……我祖母从不愿提起这个地方。",
 "Ổ khóa rỉ sét còn nguyên. Mọi ô cửa tối đen như những hốc mắt.": "锈锁依旧完好。每一扇窗都黑得像眼窝。",
