 "Cây gạo ở bên trái. Chiếc giếng đá nằm trong bóng tối bên phải.": "木棉树在左侧。石井在右边的暗处。",
 "Cổng vừa khép sau lưng. Tớ không thích cái tiếng khóa sắt đó chút nào.": "门刚在身后合上。我一点也不喜欢那铁锁的声响。",
 "Nước mưa đọng trong kẽ gạch. Cây gạo già ngả bóng lên tường vữa.": "雨水积在砖缝里。老木棉把影子斜投在灰墙上。",
