 "Cửa đôi bằng gỗ cũ. Không có ánh sáng từ phía sau.": "旧木双开门。里面没有透出光。",
 "Cánh cửa này chưa khóa hẳn. Đi cùng nhau, đừng ai tự tách nhóm.": "这扇门没有锁严。大家一起走，谁也别单独离队。",
