 "Đồng hồ dừng ở một giờ rất lạ. Tớ sẽ ghi vào sổ.": "钟停在一个很古怪的时刻。我要记进本子里。",
 "Bụi phủ kín lớp gạch bông. Những khuôn mặt trong ảnh gia đình đã bạc màu.": "灰尘覆满花砖。全家福里的面孔早已褪色。",
