 "Phía sau bên phải có một cánh cửa dẫn xuống hầm. Bếp này bị bỏ lại giữa chừng.": "右后方有一扇门通向地窖。这间厨房像是做到一半就被丢下了。",
 "Bếp củi đã tắt từ lâu. Mọi vật dụng vẫn như bị bỏ lại giữa chừng.": "柴灶早已熄灭。所有器具都像是半途被弃下。",
