 "Tớ sẽ chụp vài tấm trước khi lên. Đừng đứng quá xa nhau.": "上去之前我要拍几张。别站得太散。",
 "Bóng tay vịn đổ xiên lên ảnh chân dung cũ treo dọc tường.": "扶手的影子斜落在沿墙悬挂的旧肖像上。",
