 "Phòng trẻ bên trái, phòng làm việc bên phải... Tớ thấy chiếc gương ở cuối lối đi này rất kỳ lạ.": "左边是儿童房，右边是书房……这条走廊尽头的镜子，让我觉得很不寻常。",
