 "Tớ thấy một bé gái trong ảnh chụp... Nhưng trong phòng chẳng có ai cả.": "我在照片里看见一个小女孩……可这房里空无一人。",
 "Muỗi mùng rách thành từng dải. Chiếc gương vẫn phản chiếu căn phòng trống.": "蚊帐破成一条条。镜子仍映着空荡的房间。",
