 "Phòng làm việc của ông Hưng. Mọi thứ vẫn nằm đúng chỗ ông ấy để lại.": "Hưng 先生的书房。一切都还摆在原处。",
 "Trên mặt bàn có những vệt nước khô. Ngăn kéo và tủ kính chưa ai chạm tới.": "桌面上留有干涸的水痕。抽屉与玻璃柜都没人动过。",
