 "TẦNG HẦM · 00:15": "地下室 · 00:15",
 "Bậc đá trơn tuột xuống sâu. Dưới đó không có lấy một ô cửa sổ.": "石阶湿滑，向下延伸。下面连一扇窗也没有。",
 "Xuống đây nhớ dùng đèn pin. Tớ nghe như có người gõ từ cuối hành lang.": "下去记得用手电。我好像听见走廊尽头有人在敲。",
 "Hơi ẩm bốc lên dọc những viên gạch mục. Bóng tối đặc quánh ở cuối cầu thang.": "湿气沿着朽砖升腾。楼梯尽头的黑暗浓得化不开。",
