 "Một mảng gạch và vữa mới hơn bịt kín cuối hành lang.": "走廊尽头被一片较新的砖与灰浆封死。",
 "Mảng tường này khác hẳn phần còn lại. Phía sau có gì vậy?": "这一段墙与别处截然不同。后面是什么？",
 "Nước chảy sát mép những bao vữa khô cứng. Vữa mới hơn hẳn dãy gạch bên cạnh.": "水沿着硬结的灰浆袋边缘流过。这灰浆明显比旁边的砖新。",
