 "CĂN PHÒNG KÍN · 03:17": "密室 · 03:17",
 "Sau bức tường: những món đồ vô chủ và lời thú tội bị chôn vùi.": "墙后：无主的物件，与被埋没的忏悔。",
 "Bà Tám... Con sẽ mang tên của mọi người ra khỏi nơi này.": "Tám 婆婆……我会把所有人的名字带出这里。",
 "Nước đọng giữa lớp bùn gạch. Không có thứ gì chuyển động, chỉ có dấu vết của một bi kịch.": "水积在砖泥之间。没有东西移动，只有一场悲剧的痕迹。",
