 "Hộp sắt chôn dưới gạch": "埋在砖下的铁盒",
 "Đồ dùng bị bỏ lại": "遗留的物件",
 "Quay ra lỗ tường vỡ": "回到破开的墙洞",
 "Phòng trẻ bên kia gương": "镜后的儿童房",
