 "BÊN KIA GƯƠNG · 03:17": "镜之彼侧 · 03:17",
 "Mọi thứ bị lật ngược. Một giai điệu ru vọng từ đâu đó.": "一切都颠倒了。不知何处传来一支摇篮曲。",
 "Phòng này giống hệt, nhưng mọi thứ bị lật ngược. Tớ nghe tiếng ai đang hát khe khẽ.": "这房间一模一样，但一切都颠倒了。我听见有人在低低地唱。",
 "Chữ trên tường viết ngược. Bóng của cả nhóm không đi theo ánh đèn.": "墙上的字是反写的。我们的影子不随灯光而动。",
