 "ĐÁY GIẾNG · 03:17": "井底 · 03:17",
 "Nước đã cạn. Chỉ còn bùn lạnh và một chiếc áo trắng nhỏ.": "水已干涸。只剩冰冷的泥，和一件小小的白衣。",
 "Đây là nơi người ta giấu em. Không phải mất tích. Em bị xóa đi.": "这里是他们藏起你的地方。你不是失踪。你是被抹去了。",
 "Thành giếng đầy vết cào bé xíu, chạy dài từ đáy lên tới miệng giếng.": "井壁上满是细小的抓痕，从井底一直延伸到井口。",
 "Chiếc áo trắng nhỏ": "小小的白衣",
 "Vết cào trên thành giếng": "井壁上的抓痕",
 "Leo sợi dây lên": "攀绳而上",
 "Đại sảnh dưới ánh đỏ": "红光中的大厅",
 "CHƯƠNG 8 · BÓNG ÔNG HƯNG": "第八章 · Hưng 先生的影子",
 "ĐẠI SẢNH · ÁNH ĐỎ": "大厅 · 红光",
 "Cánh cửa chính rực đỏ. Một cái bóng cao dài trải trên nền gạch, nhưng không có ai đứng đó.": "正门泛着红光。一道细长的影子铺在砖地上，却没有人站在那里。",
 "Không có ai đứng đó, nhưng cái bóng cứ dài ra mãi. Ánh đỏ lọt qua khe cửa chính. Ông ấy đang chờ chúng ta.": "没有人站在那里，影子却不断伸长。红光从正门缝隙里漏进来。他在等我们。",
 "Đồng hồ quả lắc quay ngược. Mọi bức ảnh gia đình đều bị úp mặt xuống.": "挂钟倒着走。所有全家福都被扣了过去。",
 "Cánh cửa chính rực đỏ": "泛着红光的正门",
 "Đồng hồ chạy ngược": "倒走的钟",
 "Bộ ấm trà vỡ": "碎了的茶具",
 "Lối sang phòng thờ": "通往祠堂",
 "Gác mái dưới mái ngói": "瓦顶下的阁楼",
 "GÁC MÁI · 03:40": "阁楼 · 03:40",
 "Ánh trăng xuyên qua kẽ ngói như những mũi kim xanh. Dải vải đỏ buộc kín các xà nhà.": "月光穿过瓦隙，像一根根青色的针。红布条缠满了屋梁。",
 "Có người từng sống ở đây suốt nhiều năm, giấu mình khỏi cả ngôi nhà. Những dải vải đỏ này... là lời cầu nguyện.": "曾有人在这里住了许多年，躲着整座宅子。这些红布条……是祈愿。",
 "Bụi lơ lửng trong những vệt sáng. Mọi thứ ở đây đều được giữ gìn cẩn thận, như chờ ai đó quay lại.": "尘埃在光柱里浮游。这里的一切都被仔细保存，像在等谁回来。",
