 "Nền đá phủ rêu nằm khuất sau rễ cây.": "覆满青苔的石台藏在树根后。",
 "Những phiến đá nứt và một khe hẹp tối om dưới nền.": "石板开裂，石台下有一道幽黑窄缝。",
 "Ở đây từng có người làm lễ. Khe dưới nền đá bị che gần kín.": "这里曾有人行祭。石台下的缝隙几乎被遮住。",
 "Khe đá dưới nền": "台下的石缝",
 "Vòng đá phủ rêu": "苔覆的石环",
 "Đối chiếu những ghi chép": "对照记录",
 "Trở lại lối rừng": "返回林间小路",
 ". Tên đã được trả lại.": "。名字已经归还。",
 "Bức tranh có hai người nắm tay nhau. Nét bút trẻ con đã nhòe, nhưng có vẻ người phụ nữ rất quan trọng với em.": "画上是两个牵着手的人。孩子的笔迹已晕开，但那女人似乎对她很重要。",
 "Sổ ghi vật tư đưa xuống hầm. Có những dòng đã bị sửa; mình cần đọc kỹ hơn khi biết chuyện gì xảy ra.": "物资账被带进了地窖。有几行被改过；等弄清发生了什么，我得再细读。",
 "Các vạch phấn được xếp thành nhóm. Dưới đó còn vài nét chữ đã mờ.": "粉笔划痕被分成几组。下面还有几行字迹，已经模糊。",
 ". Tên đã được ghi vào sổ.": "。名字已记入簿中。",
 "Cái tên:": "名字：",
 ". Tìm thấy ở": "。发现于",
 "Mình vẫn cần tìm những cái tên còn lại, chị ạ.": "我还得去找剩下的名字，姐姐。",
 "Đã tìm đủ tên rồi. Chị lấy nhang ở miếu cây đa, rồi ra vườn sau, họ đang đợi chị khấn.": "名字都找齐了。姐姐去榕树庙取香，再到后院去，他们正等你上香。",
 "Nhang đã cháy hết. Những cái tên đã được trả lại.": "香已燃尽。名字已经归还。",
 "Những nấm mộ không bia. Có lẽ ai đó vẫn đến thắp nhang.": "没有碑的坟。也许还有人会来上香。",
 "VƯỜN SAU": "后院",
 "Đã hiểu": "明白了",
 "Có đủ tên rồi, nhưng chưa có nhang. Bà Tám để dành nhang trong miếu cây đa, chỗ bát hương ven rừng.": "名字齐了，却没有香。Tám 婆婆在榕树庙里留着香，就在林边那只香炉旁。",
 "Mình chọn bó nhang trong túi đồ, rồi chạm vào các nấm mộ.": "我在行囊里选中那束香，再去触碰那些坟。",
 "Vườn mộ sau biệt thự": "别墅后的坟园",
 "CÂU ĐỐ · NHỮNG CÁI TÊN": "谜题 · 那些名字",
 "Nén nhang không bén lửa. Chưa đúng người.": "香点不着。人不对。",
 "Những cái tên": "那些名字",
 "Bình, Nụ, Quyên, Thành, Giáp. Nhang bén lửa khi tên của từng người được đọc lên. Cổng sắt đã mở.": "Bình、Nụ、Quyên、Thành、Giáp。每念出一个名字，香便燃起。铁门已开。",
 "Bình. Nụ. Quyên. Thành. Giáp. Tên các bác, cháu đã gọi đủ.": "Bình。Nụ。Quyên。Thành。Giáp。各位的名字，我都叫齐了。",
 "Họ đang cười kìa chị. Em chưa thấy bác Bình cười bao giờ.": "姐姐，他们在笑呢。我从没见过 Bình 叔笑。",
 "Khói nhang bay lên rồi. Thơm quá. Hình như cả căn nhà nhẹ đi nhiều lắm.": "香烟雾起来了。好香。好像整座宅子都轻了许多。",
 "Cổng mở rồi. Chị mang các bác ra ngoài nhé. Và nhớ kể lại chuyện của em bằng cái tên của em.": "门开了。姐姐带他们出去吧。还有，记得用我的名字讲我的故事。",
 "Mình hứa. Đi thôi. Lần này đi hết con đường, không bỏ ai lại.": "我答应你。走吧。这次要把整条路走完，一个人也不留下。",
 "Két đã mở. Nhật ký của ông Hưng đã được ghi lại.": "保险柜开了。Hưng 先生的日记已经记下。",
 "Két sắt sau bức ảnh": "照片后的保险柜",
 "CÂU ĐỐ · KÉT SẮT": "谜题 · 保险柜",
 "Bấm vào từng ô số. Dưới các ô có khắc một năm, năm mà ông Hưng không bao giờ quên.": "依次按下数字格。格子下方刻着一个年份，一个 Hưng 先生永远忘不了的年份。",
 "Nhật ký ông Hưng": "Hưng 先生的日记",
 "Trang cuối ông viết: “Ta giấu chìa kho ở chỗ ta hay ngồi hóng gió, nơi nhìn xuống cả làng. Ta biết ta sẽ không bao giờ dám mở nó.”": "末页上他写道：“我把库房钥匙藏在我常坐着乘凉的地方，那里能俯瞰整个村子。我知道自己永远不敢打开它。”",
 "Trong két chỉ có một cuốn nhật ký mỏng. Trang cuối...": "保险柜里只有一本薄薄的日记。最后一页……",
 "“Ta giấu chìa kho ở chỗ ta hay ngồi hóng gió, nơi nhìn xuống cả làng.” Ông ấy biết mình sai, mà vẫn không dám mở.": "“我把库房钥匙藏在我常坐着乘凉的地方，那里能俯瞰整个村子。”他知道自己错了，却始终不敢打开。",
 "Cha em ngồi ở ban công mỗi tối. Chiếc ghế bập bênh, chị nhớ nhé.": "我父亲每晚都坐在阳台上。那把摇椅，姐姐要记住。",
 "Nghe cả tiếng gọi mà vẫn không mở cửa. Tớ chẳng thấy thương ông ta chút nào.": "他听见了呼唤，却仍不肯开门。我一点也不可怜他。",
 "Chuyến đi năm 2026": "2026 年之行",
 "Khôi, Vũ, Hà, Chi và Vy đến Đồng Chay để tìm hiểu chuyện năm xưa của biệt thự Vân Hòa qua các bài báo thời ấy.": "Khôi、Vũ、Hà、Chi 与 Vy 来到 Đồng Chay，借当年的报纸追查 Vân Hòa 别墅的旧事。",
 "Ba bài báo cũ (1986, 1988, 1989)": "三篇旧报道（1986、1988、1989）",
 "Tin ngắn về lễ cầu mưa ở Đồng Chay (1986) có nhắc ông Hưng ở biệt thự Vân Hòa. Bài năm 1988 nói gia chủ khóa cổng rồi rời đi. Bài năm 1989 viết về ngôi nhà bỏ hoang trên đồi. Không bài nào nêu rõ chuyện gì đã xảy ra; người viết cũng không ghi nguồn tin.": "一则关于 Đồng Chay 求雨礼的短讯（1986 年）提到 Vân Hòa 别墅的 Hưng 先生。1988 年的文章说屋主锁上大门后离去。1989 年的文章写的是山丘上那座荒宅。没有一篇说明究竟发生了什么；作者也没有注明消息来源。",
 "Ông Tùng ngồi đối diện trong căn nhà bên bàn thờ chị Quế": "Tùng 先生坐在对面，就在 Quế 姐家神台旁",
 "Bà bán nước ngồi đối diện bên bàn trà": "卖水婆婆坐在对面，茶桌旁",
 "Thầy Nguyên ngồi đối diện bên bàn xem quẻ và ba đồng xu": "Nguyên 法师坐在对面，桌上有卦盘与三枚铜钱",
