 "Hãy mở lại trang cuối của nhật ký sau khi trở về từ ký ức.": "从记忆中返回后，再翻开日记的最后一页。",
 "TƯ LIỆU": "资料",
 "Các ký hiệu ở đây chưa đủ rõ để kết luận. Có thể có sách hoặc ghi chép trong những phòng khác giúp đối chiếu.": "这里的符号还不够明确，无法下结论。别的房间里也许有书或笔记可供对照。",
 "CÂU ĐỐ · CHƯA ĐỦ DỮ KIỆN": "谜题 · 证据不足",
 "Chiếc bát không người nhận": "无人认领的碗",
 "Hãy đọc trang “Bữa cơm đêm” trong sổ bếp trước khi đối chiếu.": "对照之前，先读厨房簿里的“夜饭”那一页。",
 "Chưa khớp với các tài liệu. Thử xem lại từng chi tiết.": "与资料不符。再把每个细节看一遍。",
