 "Tiếng đập cửa và tiếng người gọi vọng lên từ bên dưới. Then gỗ cài từ phía ngoài.": "敲门声和呼喊声从下面传上来。木门闩是从外面闩上的。",
 "Hơi nóng và mùi khói đồ lễ lọt qua khe cửa.": "热气和祭品的烟味从门缝里透出来。",
 "Tiếng gọi sau cánh cửa": "门后的呼喊",
 "Then cửa gỗ": "木门闩",
