 "Cha kéo Nhài ra ngoài": "父亲把 Nhài 拉开",
 "Hành lang bếp, cửa hầm vẫn đóng": "厨房过道，地下室门仍关着",
 "HÀNH LANG BẾP · 1988": "厨房过道 · 1988",
 "Tiếng đập cửa nhỏ dần phía sau. Ngoài sân có ánh đèn của bàn tế.": "敲击声在身后渐渐弱下去。院子里有祭台的灯光。",
 "Nhài ngồi bệt xuống sàn nơi cha vừa gạt em ra.": "Nhài 就在父亲刚刚把她推开的地方跌坐下去。",
