 "Mưa xối xuống sân. Chiếc đèn bão nằm nghiêng bên miệng giếng.": "雨倾泻在院里。马灯歪倒在井口旁。",
 "Mưa tạt rát mặt. Trên miệng giếng, nắp gỗ đã xô lệch.": "雨打着脸生疼。井口的木盖已被撞歪。",
 "Thứ gì đó đặt trên thành giếng": "搁在井沿上的东西",
 "Bám tường chạy vòng bên trái": "贴墙向左绕跑",
 "Chạy thẳng ngang miệng giếng": "径直跑过井口",
 "Chiếc giày vải nhỏ": "一只小布鞋",
