 "ĐƯỜNG LÀNG · 1988": "村路 · 1988",
 "Một đốm sáng rất xa. Em chưa bao giờ tới được.": "很远的一点光。她从未走到那里。",
 "Con đường bùn kéo dài giữa hai rặng tre.": "泥路在两道竹林间延伸。",
 "Đốm sáng xa xa": "远处的一点光",
