 "Sương loãng dần. Những dải vải đỏ khẽ lay trên cành.": "雾渐渐薄了。红布带在枝头轻轻摆动。",
 "Cây đa, cây gạo và một bàn thờ đá phủ rêu.": "一棵榕树、一棵木棉，还有一座覆满青苔的石祭坛。",
 "Bàn thờ đá trong rừng": "林中的石祭坛",
 "Dải vải đỏ có thêu chữ": "绣着字的红布带",
 "Hoa gạo đỏ trên cành": "枝头的红木棉花",
