 "Mái ngói rêu, giàn phơi lá thuốc và chiếc xe đạp cũ dựa tường.": "长满青苔的瓦顶，晒药的架子，还有一辆靠墙的旧自行车。",
 "Căn nhà cuối xóm, cửa mở hé. Có mùi lá thuốc phơi nắng.": "村尾那间屋子，门半开着。飘着草药晒过太阳的味道。",
 "Cánh cửa nhà ông Tùng": "Tùng 先生家的门",
 "Bàn trà ngoài hiên": "廊下的茶桌",
 "Giàn phơi lá thuốc": "晒药架",
