 "Bàn thờ nhỏ có ảnh một cô gái đội khăn, cạnh khăn chàm và túi lá thuốc.": "小神台上摆着一张照片，照片里的姑娘裹着头巾，旁边是一条靛蓝头巾和一袋草药。",
 "Căn nhà gọn gàng, sạch sẽ, thơm mùi nhang và lá thuốc.": "屋子整洁干净，弥漫着香与草药的气味。",
