 "Bà Tám thừa nhận đã đứng im khi nghe tiếng đập": "Tám 婆婆承认听见砸门声时站着不动",
 "Trong hầm có lối ngầm ra giếng": "地窖里有暗通水井的路",
 "Các mộ gió chứa hài cốt": "那些衣冠冢里埋着遗骨",
 "Thành tự khóa tất cả mọi người ở trong": "Thành 把所有人都锁在了里面",
 "Phiếu vật tư, kết cấu cửa và lời khai là ba loại nguồn riêng cần được giữ cùng nhau.": "物资单、门的构造与口供，是三类各自独立的来源，须放在一处看。",
 "Đối chiếu một ghi chép vật tư, một bản kiểm tra cửa và một lời khai.": "把一份物资记录、一页门检记录和一份口供对照。",
 "Bốn mảnh niên biểu": "年表的四个片段",
 "Sắp các dấu vết theo thời gian, từ sớm nhất đến muộn nhất. Hãy tìm ngày tháng trong cả hai cuốn sổ.": "按时间先后排列这些痕迹，从最早到最晚。日期要在两本簿子里找。",
 "Những nấm mộ gió được dựng": "衣冠冢立起",
