 "Hai cuốn sổ đặt việc cấp vật tư trước đêm lễ; những nấm mộ gió xuất hiện sau đó.": "两本簿子都把发料之事放在礼前；衣冠冢则在那之后才出现。",
 "Tìm hai ngày trong sổ vật tư, rồi đối chiếu đêm lễ và sáng hôm sau.": "在物资簿里找出两个日期，再对礼夜和第二日早晨。",
